-- Nobita
-- Khong sua file nay. Moi thay doi lam hong bo giai ma.
local _mrrzxw = 58
local _hbtnvt = 201
local _zfutwf = 102
local _pswxnd = ""

local _cmcqfk = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _lernby(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _dguimq(d)
	d = d:gsub("[^" .. _cmcqfk .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_cmcqfk:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _zhomfd = _dguimq(_pswxnd)
local _cibpfw = { _mrrzxw, _hbtnvt, _zfutwf }
local _vjpyvd = {}
for i = 1, #_zhomfd do
	_vjpyvd[i] = string.char(_lernby(_zhomfd:byte(i), _cibpfw[(i - 1) % 3 + 1]))
end

local _ihlfae = load or loadstring
local _xtahlh, _uqhrsi = _ihlfae(table.concat(_vjpyvd), "=w")
if not _xtahlh then
	gg.alert("File hong: " .. tostring(_uqhrsi))
	os.exit()
end
_xtahlh()
